insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('bmlt-toxicologytdm1-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"Therapeutic drug monitoring is most useful when a medicine has:","translation":"","options":["A narrow therapeutic index","No systemic absorption","No adverse effects","Only topical action"],"correctIndex":0,"explanation":"TDM helps optimize drugs with a narrow margin between effective and toxic concentrations.","explanationNe":"Effective र toxic dose बीचको अन्तर कम भएका औषधिमा TDM उपयोगी हुन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"A trough drug level is collected:","translation":"","options":["Immediately before the next dose","At the time of peak effect always","One week after stopping therapy","Only after an overdose"],"correctIndex":0,"explanation":"A trough is measured just before the next scheduled dose.","explanationNe":"Trough level अर्को dose दिनुअघि लिइन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"A peak drug level is generally collected:","translation":"","options":["At the specified time after a dose when concentration is expected to peak","Before the first dose in every case","Only before the next dose","At any random time"],"correctIndex":0,"explanation":"Peak timing depends on drug, route and protocol.","explanationNe":"Peak sample को समय औषधि, route र protocol अनुसार हुन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"Which specimen is commonly used for many therapeutic drug levels?","translation":"","options":["Serum or plasma","Hair only","Stool only","Saliva always"],"correctIndex":0,"explanation":"Many TDM assays use serum or plasma collected at defined times.","explanationNe":"धेरै TDM परीक्षणमा निश्चित समयमा लिइएको serum वा plasma प्रयोग हुन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"A drug level is difficult to interpret without knowing:","translation":"","options":["Dose and time of last administration","Patient''s shoe size","Tube color alone","Laboratory room number"],"correctIndex":0,"explanation":"Dose timing is essential for interpreting peak, trough and steady-state levels.","explanationNe":"Peak, trough र steady-state level बुझ्न dose को समय आवश्यक हुन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"Steady state is usually approached after approximately:","translation":"","options":["4–5 half-lives","One minute for all drugs","One half-life always","Twenty half-lives for every drug"],"correctIndex":0,"explanation":"Most drugs reach near steady state after about four to five half-lives.","explanationNe":"धेरै औषधि करिब 4–5 half-life पछि steady state नजिक पुग्छन्।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"A drug''s half-life is the time required for its plasma concentration to:","translation":"","options":["Decrease by about 50%","Double in every patient","Become zero","Reach peak immediately"],"correctIndex":0,"explanation":"Half-life describes the time for concentration to fall by half under defined conditions.","explanationNe":"Half-life भनेको concentration आधा हुन लाग्ने समय हो।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"Which organ is most important for metabolism of many drugs?","translation":"","options":["Liver","Spleen only","Skin only","Teeth"],"correctIndex":0,"explanation":"Many drugs undergo hepatic metabolism, though pathways vary.","explanationNe":"धेरै औषधिको metabolism liver मा हुन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"Reduced renal function can cause accumulation of a drug that is:","translation":"","options":["Primarily eliminated by the kidneys","Only metabolized in skin","Not absorbed","Always inhaled"],"correctIndex":0,"explanation":"Renal impairment may reduce clearance of renally eliminated drugs.","explanationNe":"Kidney function घट्दा renal elimination हुने औषधि जम्मा हुन सक्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"Acetaminophen/paracetamol overdose can cause serious injury to the:","translation":"","options":["Liver","Lens only","Thyroid only","Ear canal"],"correctIndex":0,"explanation":"Toxic metabolite formation can cause severe hepatic injury in overdose.","explanationNe":"Overdose मा toxic metabolite ले गम्भीर liver injury गराउन सक्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"The antidote used for acetaminophen poisoning is:","translation":"","options":["N-acetylcysteine","Atropine","Naloxone","Vitamin K"],"correctIndex":0,"explanation":"N-acetylcysteine replenishes glutathione and reduces toxicity.","explanationNe":"N-acetylcysteine ले glutathione पुनःपूर्ति गरी toxicity घटाउँछ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"Opioid toxicity commonly causes:","translation":"","options":["Respiratory depression and reduced consciousness","Severe hypertension in every case","Mydriasis always","Increased respiratory rate"],"correctIndex":0,"explanation":"Opioids can suppress respiratory drive and consciousness.","explanationNe":"Opioid ले श्वासप्रश्वास र चेतना दबाउन सक्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"The specific reversal agent for opioid overdose is:","translation":"","options":["Naloxone","Flumazenil","N-acetylcysteine","Pralidoxime"],"correctIndex":0,"explanation":"Naloxone is an opioid receptor antagonist used to reverse opioid toxicity.","explanationNe":"Naloxone opioid receptor antagonist हो र opioid toxicity उल्ट्याउन प्रयोग हुन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"Organophosphate poisoning may cause:","translation":"","options":["Muscarinic symptoms such as salivation and bronchorrhea","Dry skin and absent secretions only","Isolated hyperglycemia always","No cholinergic signs"],"correctIndex":0,"explanation":"Acetylcholinesterase inhibition causes excess cholinergic activity.","explanationNe":"Acetylcholinesterase inhibition ले cholinergic लक्षण बढाउँछ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"Atropine in organophosphate poisoning primarily treats:","translation":"","options":["Muscarinic effects","DNA mutation","Methemoglobinemia","Iron deficiency"],"correctIndex":0,"explanation":"Atropine blocks muscarinic receptors and helps control secretions and bronchospasm.","explanationNe":"Atropine ले muscarinic receptor block गरी secretion र bronchospasm घटाउँछ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"Pralidoxime may help by:","translation":"","options":["Reactivating acetylcholinesterase before aging occurs","Binding all heavy metals","Reversing opioid receptors","Treating acetaminophen toxicity"],"correctIndex":0,"explanation":"Pralidoxime can reactivate inhibited acetylcholinesterase if given appropriately.","explanationNe":"Pralidoxime ले उचित समयमा inhibited acetylcholinesterase पुनः सक्रिय गर्न सक्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"Carbon monoxide poisoning reduces oxygen delivery by forming:","translation":"","options":["Carboxyhemoglobin","Methemoglobin only","Oxyhemoglobin excess","Albumin-bound oxygen"],"correctIndex":0,"explanation":"Carbon monoxide binds hemoglobin with high affinity.","explanationNe":"Carbon monoxide hemoglobin सँग उच्च affinity ले जोडिन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"A standard two-wavelength pulse oximeter may be misleading in:","translation":"","options":["Carbon monoxide poisoning","Simple iron deficiency only","Mild dehydration only","Hyperlipidemia"],"correctIndex":0,"explanation":"Conventional pulse oximetry may not distinguish carboxyhemoglobin accurately.","explanationNe":"सामान्य pulse oximeter ले carboxyhemoglobin सही छुट्याउन सक्दैन।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',19,'{"question":"Methanol poisoning may cause:","translation":"","options":["Metabolic acidosis and visual disturbances","Isolated thrombocytosis","Improved vision","Only mild skin rash"],"correctIndex":0,"explanation":"Methanol metabolites can cause severe acidosis and optic injury.","explanationNe":"Methanol metabolite ले acidosis र आँखाको क्षति गराउन सक्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',20,'{"question":"Ethylene glycol poisoning may be associated with:","translation":"","options":["Metabolic acidosis and calcium oxalate crystals","High serum calcium always","Only respiratory alkalosis","No renal injury"],"correctIndex":0,"explanation":"Metabolites can cause acidosis and renal injury; oxalate crystals may occur.","explanationNe":"Metabolite ले acidosis र kidney injury गराउन सक्छ; oxalate crystal देखिन सक्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"Lead exposure may cause:","translation":"","options":["Microcytic anemia and basophilic stippling","Macrocytosis in every case","High platelet count always","Low blood glucose only"],"correctIndex":0,"explanation":"Lead interferes with heme synthesis and may cause basophilic stippling.","explanationNe":"Lead ले heme synthesis बिगारेर basophilic stippling सहित anemia गराउन सक्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"A common biomarker for recent significant lead exposure is:","translation":"","options":["Blood lead concentration","Urine glucose alone","Serum amylase","ESR only"],"correctIndex":0,"explanation":"Blood lead level is used to assess exposure, interpreted by clinical context.","explanationNe":"Blood lead concentration ले lead exposure मूल्याङ्कन गर्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',23,'{"question":"An elevated anion gap metabolic acidosis can be seen in:","translation":"","options":["Some toxic alcohol and salicylate poisonings","All uncomplicated allergies","Iron deficiency only","Normal saline infusion only"],"correctIndex":0,"explanation":"Certain toxins and their metabolites increase unmeasured anions.","explanationNe":"केही toxin र metabolite ले unmeasured anion बढाएर anion gap acidosis गराउँछन्।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"Activated charcoal is most effective when:","translation":"","options":["Given early for an adsorbable toxin after airway safety is assessed","Used for every corrosive ingestion","Given to an unconscious patient without airway protection","Used to treat all metals equally"],"correctIndex":0,"explanation":"Charcoal adsorbs some toxins; timing and airway protection are critical.","explanationNe":"Charcoal ले केही toxin adsorb गर्छ; समय र airway safety महत्त्वपूर्ण हुन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"In suspected poisoning, the laboratory''s priority is to:","translation":"","options":["Support urgent clinical assessment with appropriate tests and communication","Delay all results until routine batch","Provide an antidote without clinical authorization","Ignore specimen timing"],"correctIndex":0,"explanation":"Toxicology results must be interpreted rapidly with clinical findings and communicated appropriately.","explanationNe":"Toxicology result clinical अवस्था सँग मिलाएर छिटो communicate गर्नुपर्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"A patient on digoxin has nausea, visual disturbance and an elevated serum level. This may indicate:","translation":"","options":["Digoxin toxicity","Iron deficiency","Opioid withdrawal","Normal therapeutic effect"],"correctIndex":0,"explanation":"Symptoms with an elevated appropriately timed level support digoxin toxicity.","explanationNe":"लक्षण र उचित समयमा लिएको बढेको level digoxin toxicity सँग मेल खान्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2,'{"question":"A lithium level is requested. Which information is especially important?","translation":"","options":["Time since last dose and steady-state status","Patient''s blood group only","Urine color only","Whether the sample is in a glass tube"],"correctIndex":0,"explanation":"Lithium interpretation commonly depends on standardized timing, often a 12-hour level.","explanationNe":"Lithium level बुझ्न dose पछिको समय, प्रायः 12-hour level, महत्त्वपूर्ण हुन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"A patient taking phenytoin has low albumin. Total phenytoin appears low but toxicity is suspected. Consider measuring:","translation":"","options":["Free phenytoin concentration","Urine ketone","Serum sodium only","Total bilirubin only"],"correctIndex":0,"explanation":"Phenytoin is highly protein-bound; low albumin can alter the free active fraction.","explanationNe":"Phenytoin protein-bound हुन्छ; albumin कम हुँदा free active fraction बदलिन सक्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"A trough sample for an antibiotic is drawn several hours after the next dose. The result may be:","translation":"","options":["Misleading because collection timing was incorrect","Always a true trough","Equivalent to a peak","Unaffected by dose timing"],"correctIndex":0,"explanation":"Trough levels must be collected at the specified pre-dose time.","explanationNe":"Trough sample तोकिएको dose-अघिको समयमा लिनुपर्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"A patient with renal impairment receives a renally cleared drug and develops a high level. Likely mechanism?","translation":"","options":["Reduced drug clearance","Increased renal clearance","Faster elimination","No pharmacokinetic change"],"correctIndex":0,"explanation":"Reduced kidney function can decrease elimination and increase concentration.","explanationNe":"Kidney function कम हुँदा clearance घटेर drug level बढ्न सक्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-006','BMLT','BMLT NHPC Licensing','mock','free',6,'{"question":"A suspected paracetamol overdose patient arrives early and feels well. What is the best principle?","translation":"","options":["Urgent assessment and timed serum level according to poisoning protocol","Wait for jaundice before testing","A normal early symptom check excludes toxicity","Give activated charcoal days later"],"correctIndex":0,"explanation":"Early poisoning may be asymptomatic; time-based assessment guides management.","explanationNe":"सुरुको overdose मा लक्षण नहुन सक्छ; समयअनुसार serum level र protocol आवश्यक हुन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-007','BMLT','BMLT NHPC Licensing','mock','free',7,'{"question":"A patient with opioid overdose is unresponsive and breathing slowly. Which immediate concern is most important?","translation":"","options":["Airway and ventilation support with emergency care","Wait for toxicology result first","Give oral fluids","Collect hair sample"],"correctIndex":0,"explanation":"Respiratory depression is life-threatening and requires immediate supportive care and naloxone when indicated.","explanationNe":"Respiratory depression ज्यान जोखिमपूर्ण हुन्छ; तुरुन्त airway support र आवश्यक परे naloxone चाहिन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-008','BMLT','BMLT NHPC Licensing','mock','free',8,'{"question":"A worker exposed to pesticide has pinpoint pupils, excessive secretions and wheezing. This pattern suggests:","translation":"","options":["Cholinergic poisoning","Anticholinergic toxicity","Carbon monoxide only","Lead exposure only"],"correctIndex":0,"explanation":"Miosis, secretions and bronchospasm are classic cholinergic features.","explanationNe":"सानो pupil, secretion र bronchospasm cholinergic poisoning का लक्षण हुन्।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-009','BMLT','BMLT NHPC Licensing','mock','free',9,'{"question":"A patient exposed to smoke has headache and confusion; carboxyhemoglobin is elevated. Diagnosis?","translation":"","options":["Carbon monoxide poisoning","Methanol poisoning","Iron overdose","Lithium toxicity"],"correctIndex":0,"explanation":"Elevated carboxyhemoglobin with exposure history supports CO poisoning.","explanationNe":"Exposure history र carboxyhemoglobin बढ्नु CO poisoning सँग मेल खान्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-010','BMLT','BMLT NHPC Licensing','mock','free',10,'{"question":"A patient who ingested methanol develops blurred vision and high anion-gap acidosis. This is:","translation":"","options":["A toxic alcohol emergency","A routine viral illness","A normal post-meal change","Iron deficiency"],"correctIndex":0,"explanation":"Methanol can cause optic toxicity and severe metabolic acidosis.","explanationNe":"Methanol ले optic toxicity र गम्भीर metabolic acidosis गराउन सक्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-011','BMLT','BMLT NHPC Licensing','mock','free',11,'{"question":"A suspected ethylene glycol case has renal injury and calcium oxalate crystals. These findings support:","translation":"","options":["Ethylene glycol toxicity","Paracetamol toxicity","Opioid overdose","Digoxin toxicity"],"correctIndex":0,"explanation":"Ethylene glycol metabolites may cause oxalate crystal deposition and renal damage.","explanationNe":"Ethylene glycol metabolite ले oxalate crystal र kidney damage गराउन सक्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-012','BMLT','BMLT NHPC Licensing','mock','free',12,'{"question":"A blood lead result is elevated in a child. The laboratory should:","translation":"","options":["Promptly report according to critical/public health policy and ensure confirmation as indicated","Ignore it if CBC is normal","Diagnose by urine dipstick only","Repeat after several years only"],"correctIndex":0,"explanation":"Elevated lead is clinically important and requires timely reporting and follow-up.","explanationNe":"बढेको lead level महत्त्वपूर्ण हुन्छ; policy अनुसार तुरुन्त report र follow-up चाहिन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-013','BMLT','BMLT NHPC Licensing','mock','free',13,'{"question":"A serum drug concentration was collected at an undocumented time. The safest interpretation is:","translation":"","options":["Interpret cautiously and request correctly timed repeat if needed","Treat it as a trough automatically","Treat it as a peak automatically","Use it to change dose without review"],"correctIndex":0,"explanation":"Without collection timing, many drug levels cannot be interpreted reliably.","explanationNe":"Sample time नहुँदा धेरै drug level विश्वसनीय रूपमा interpret गर्न सकिँदैन।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-014','BMLT','BMLT NHPC Licensing','mock','free',14,'{"question":"A toxicology screen is negative but clinical suspicion remains high. What should be considered?","translation":"","options":["Assay limitations, detection window and confirmatory testing","Poisoning is impossible","The patient is malingering","All toxic substances are detected by one screen"],"correctIndex":0,"explanation":"Screening tests have limited targets and detection windows; confirmatory methods may be needed.","explanationNe":"Screening test का target र detection window सीमित हुन्छन्; confirmatory test चाहिन सक्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-015','BMLT','BMLT NHPC Licensing','mock','free',15,'{"question":"A urine drug screen is positive for a medication prescribed to the patient. The result should be:","translation":"","options":["Interpreted with medication history and assay limitations","Automatically reported as illicit use","Ignored completely","Used to identify exact dose"],"correctIndex":0,"explanation":"Immunoassay screens may cross-react and do not always identify exact drug or dose.","explanationNe":"Immunoassay मा cross-reaction हुन सक्छ; history र limitation अनुसार interpret गर्नुपर्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-016','BMLT','BMLT NHPC Licensing','mock','free',16,'{"question":"A patient may have taken a large amount of iron tablets. Which test can help assess exposure in acute poisoning?","translation":"","options":["Serum iron at the appropriate time with clinical evaluation","Serum albumin only","ESR","Blood group"],"correctIndex":0,"explanation":"Serum iron measurement may support assessment, interpreted with timing and symptoms.","explanationNe":"Acute iron poisoning मा उचित समयमा serum iron र clinical assessment उपयोगी हुन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-017','BMLT','BMLT NHPC Licensing','mock','free',17,'{"question":"A toxicology specimen arrives leaking and without clear identification. The laboratory should:","translation":"","options":["Follow biosafety and specimen rejection/identity policy","Open it without PPE","Guess the patient''s identity","Transfer it to an unlabeled tube"],"correctIndex":0,"explanation":"Unsafe or unidentified specimens must be managed under safety and identification procedures.","explanationNe":"Leak भएको वा पहिचान अस्पष्ट sample लाई safety र identification policy अनुसार handle गर्नुपर्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-018','BMLT','BMLT NHPC Licensing','mock','free',18,'{"question":"A high salicylate concentration is suspected in a patient with tinnitus and rapid breathing. Likely poisoning?","translation":"","options":["Salicylate toxicity","Lithium toxicity","Lead toxicity","Carbon monoxide only"],"correctIndex":0,"explanation":"Tinnitus and respiratory stimulation are common features of salicylate poisoning.","explanationNe":"Tinnitus र छिटो श्वास salicylate toxicity मा देखिन सक्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-019','BMLT','BMLT NHPC Licensing','mock','free',19,'{"question":"A patient with suspected toxic ingestion has a severe acid-base disturbance. Which lab test is important promptly?","translation":"","options":["Blood gas and electrolytes with calculated anion gap","Only total cholesterol","Only blood group","Only stool occult blood"],"correctIndex":0,"explanation":"Blood gas and electrolytes help characterize acid-base status and anion gap.","explanationNe":"Blood gas र electrolyte ले acid-base अवस्था र anion gap मूल्याङ्कन गर्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-020','BMLT','BMLT NHPC Licensing','mock','free',20,'{"question":"A drug has a narrow therapeutic index. The clinician requests a level after dose adjustment. Best sample timing?","translation":"","options":["At the validated time after an appropriate steady state, per protocol","Immediately after every dose regardless of drug","At any random time","Only before treatment begins"],"correctIndex":0,"explanation":"TDM should follow drug-specific timing and steady-state guidance when applicable.","explanationNe":"TDM मा drug-specific timing र आवश्यक steady state अनुसार sample लिनुपर्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-021','BMLT','BMLT NHPC Licensing','mock','free',21,'{"question":"A toxicology result is critically high. What should the laboratory do?","translation":"","options":["Verify according to policy, promptly notify clinician and document","Hold it until the monthly meeting","Send only by untracked message","Change the value to the reference interval"],"correctIndex":0,"explanation":"Critical results require timely communication and documentation.","explanationNe":"Critical result policy अनुसार तुरुन्त notify र document गर्नुपर्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-022','BMLT','BMLT NHPC Licensing','mock','free',22,'{"question":"A sample for volatile alcohol analysis is collected. Which handling is generally important?","translation":"","options":["Use suitable sealed container and minimize evaporation per protocol","Leave the tube open","Warm it to boiling","Transfer repeatedly into open cups"],"correctIndex":0,"explanation":"Volatile analytes can be lost by evaporation; appropriate sealing and handling matter.","explanationNe":"Volatile analyte उड्न सक्छ; उपयुक्त sealed container र handling आवश्यक हुन्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-023','BMLT','BMLT NHPC Licensing','mock','free',23,'{"question":"A clinician asks whether a toxicology test can prove impairment at the time of an incident. The lab should explain:","translation":"","options":["A detected substance or level may not directly establish impairment; context and test limitations matter","Any positive result proves impairment","Urine concentration always equals blood concentration","A screening test gives exact time of ingestion"],"correctIndex":0,"explanation":"Detection does not automatically establish timing, dose or functional impairment.","explanationNe":"Positive result ले ingestion को समय, dose वा impairment स्वतः प्रमाणित गर्दैन।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-024','BMLT','BMLT NHPC Licensing','mock','free',24,'{"question":"A patient is suspected of poisoning but the agent is unknown. The lab should:","translation":"","options":["Support targeted testing guided by clinical history and poison-control/clinical team","Run every available test without prioritization","Delay urgent stabilization","Report a guessed agent"],"correctIndex":0,"explanation":"Testing should be prioritized with clinical information while emergency care proceeds.","explanationNe":"Clinical history र team guidance अनुसार targeted testing प्राथमिकता दिनुपर्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true),
('bmlt-toxicologytdm1-mock-025','BMLT','BMLT NHPC Licensing','mock','free',25,'{"question":"A therapeutic drug level is above the reference therapeutic range but the patient is asymptomatic. The result should be:","translation":"","options":["Reviewed with timing, clinical status and prescribing team before interpretation","Automatically labeled fatal","Ignored","Used to diagnose poisoning without context"],"correctIndex":0,"explanation":"Reference ranges guide but do not replace clinical interpretation and sample timing.","explanationNe":"Reference range मार्गदर्शन हो; timing र clinical अवस्था सहित interpret गर्नुपर्छ।","topic":"Clinical Toxicology & Therapeutic Drug Monitoring"}'::jsonb,true)
